class HuffmanTreeNode:
    def __init__(self, data, freq):
        self.data = data
        self.freq = freq
        self.left = None
        self.right = None

    def add_left_child(self, node):
        self.left = node

    def add_right_child(self, node):
        self.right = node

def generate_huffman_codes(self, node=None, code="", huffman_code_map={}):
